// pages/catalog/Catalog.js
import { useState, useMemo } from 'react';
import { useAuthContext } from '../../hooks/useAuthContext';
import { useAdmin } from '../../hooks/UseAdmin';
import CourseCard from '../../components/CourseCard/CourseCard';
import CourseFilters from '../../components/CourseFilters/CourseFilters';
import SearchBar from '../../components/SearchBar/SearchBar';
import './catalog.css';
  // Données mock - à remplacer par Firebase plus tard
  const mockCourses = [
    {
      id: 1,
      title: "React Avancé - Les Hooks et Context API",
      description: "Maîtrisez React avec les Hooks modernes, Context API et Redux. Développez des applications complexes avec les meilleures pratiques.",
      price: 89,
      originalPrice: 129,
      category: "Développement",
      image: "/images/react.jpg",
      instructor: "Ahmed Ben Ali",
      rating: 4.8,
      students: 1240,
      duration: "12h 30min",
      level: "Intermédiaire",
      featured: true
    },
    {
      id: 2,
      title: "UI/UX Design avec Figma",
      description: "Apprenez à créer des interfaces utilisateur modernes et intuitives. Prototypage avancé et design system.",
      price: 69,
      originalPrice: 99,
      category: "Design",
      image: "/images/figma.webp",
      instructor: "Sarah Trabelsi",
      rating: 4.9,
      students: 890,
      duration: "8h 15min",
      level: "Débutant",
      featured: false
    },
    {
      id: 3,
      title: "Marketing Digital 2024",
      description: "Stratégies complètes de marketing digital: SEO, réseaux sociaux, email marketing et analytics.",
      price: 79,
      originalPrice: 119,
      category: "Business",
      image: "/images/marketing-digital.jpg",
      instructor: "Mohamed Dridi",
      rating: 4.7,
      students: 1560,
      duration: "10h 45min",
      level: "Tous niveaux",
      featured: true
    },
    {
      id: 4,
      title: "Python & Data Science",
      description: "Devenez data scientist avec Python. Pandas, NumPy, Matplotlib et machine learning.",
      price: 99,
      originalPrice: 149,
      category: "Développement",
      image: "/images/python.jpeg",
      instructor: "Leila Mansour",
      rating: 4.8,
      students: 2100,
      duration: "15h 20min",
      level: "Avancé",
      featured: false
    },
    {
      id: 5,
      title: "Adobe Photoshop Pro",
      description: "Maîtrisez Photoshop de A à Z. Retouche photo, montage avancé et création digitale.",
      price: 59,
      originalPrice: 89,
      category: "Design",
      image: "/images/adobe.jpg",
      instructor: "Youssef Guedira",
      rating: 4.6,
      students: 750,
      duration: "9h 10min",
      level: "Débutant",
      featured: false
    },
    {
      id: 6,
      title: "Gestion de Projet Agile",
      description: "Méthodologies Agile, Scrum, Kanban. Devenez chef de projet certifié.",
      price: 85,
      originalPrice: 125,
      category: "Business",
      image: "/images/agile.jpeg",
      instructor: "Nadia Boukadida",
      rating: 4.9,
      students: 980,
      duration: "7h 45min",
      level: "Intermédiaire",
      featured: true
    }
  ];

export default function Catalog() {
  const { user } = useAuthContext();
  const { isAdmin } = useAdmin();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('Tous');
  const [sortBy, setSortBy] = useState('popular');



   const filteredCourses = useMemo(() => {
    let filtered = mockCourses;

    // Filtre par recherche
    if (searchTerm) {
      filtered = filtered.filter(course =>
        course.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        course.description.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }


    // Filtre par catégorie
    if (selectedCategory !== 'Tous') {
      filtered = filtered.filter(course => course.category === selectedCategory);
    }

    // Tri
    switch (sortBy) {
      case 'price-low':
        filtered = [...filtered].sort((a, b) => a.price - b.price);
        break;
      case 'price-high':
        filtered = [...filtered].sort((a, b) => b.price - a.price);
        break;
      case 'rating':
        filtered = [...filtered].sort((a, b) => b.rating - a.rating);
        break;
      case 'students':
        filtered = [...filtered].sort((a, b) => b.students - a.students);
        break;
      default:
        // Popular par défaut (featured first, then by students)
        filtered = [...filtered].sort((a, b) => {
          if (a.featured && !b.featured) return -1;
          if (!a.featured && b.featured) return 1;
          return b.students - a.students;
        });
    }

    return filtered;
  }, [searchTerm, selectedCategory, sortBy]);

  const categories = ['Tous', 'Développement', 'Design', 'Business'];

  return (
    <div className="catalog-page">
      <div className="catalog-header">
        <h1>Explorez Notre Catalogue de Cours</h1>
        <p>Découvrez {mockCourses.length} cours professionnels pour booster votre carrière</p>
      </div>

      <div className="catalog-controls">
        <SearchBar 
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
        />

        <CourseFilters
          categories={categories}
          selectedCategory={selectedCategory}
          onCategoryChange={setSelectedCategory}
          sortBy={sortBy}
          onSortChange={setSortBy}
        />
      </div>

      <div className="catalog-results">
        <div className="results-info">
          <span className="results-count">
            {filteredCourses.length} cours trouvés
            {selectedCategory !== 'Tous' && ` dans "${selectedCategory}"`}
            {searchTerm && ` pour "${searchTerm}"`}
          </span>
        </div>

        {filteredCourses.length === 0 ? (
          <div className="no-results">
            <h3>Aucun cours trouvé</h3>
            <p>Essayez de modifier vos critères de recherche ou de filtrage</p>
          </div>
        ) : (
          <div className="course-grid">
            {filteredCourses.map(course => (
              <CourseCard 
                key={course.id}
                course={course}
                isAdmin={isAdmin}
                user={user}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
